def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application object provides the expected attributes
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    # Default schema template that captures common metadata and status fields.
    default_schema = {
        "type": "object",
        "properties": {
            "metadata": {"type": "object"},
            "status": {"type": "object"},
        },
        "required": ["metadata", "status"],
    }

    # Iterate over the resources declared in the manifest.
    for resource_name, resource in app.spec.manifest.items():
        # Accept either a dict or an object that acts like a dict.
        if isinstance(resource, dict):
            # Skip if the resource already defines an observer schema.
            if resource.get("observer_schema") is not None:
                continue
            resource["observer_schema"] = default_schema
        else:
            # For non-dict objects, attempt to set an attribute if it exists.
            if hasattr(resource, "observer_schema"):
                if getattr(resource, "observer_schema") is not None:
                    continue
                setattr(resource, "observer_schema", default_schema)

    # No explicit return value is required. The function mutates the
    # application spec in place.<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for res in getattr(app, 'spec', None).manifest:
        # Skip resources that already have a custom observer schema
        if hasattr(res, 'observer_schema') and res.observer_schema:
            continue

        # Helper to retrieve attributes whether res is a dict or an object
        def _attr(o, name, default=None):
            if isinstance(o, dict):
                return o.get(name, default)
            return getattr(o, name, default)

        api_version = _attr(res, 'apiVersion')
        kind = _attr(res, 'kind')
        metadata = _attr(res, 'metadata')
        spec = _attr(res, 'spec')

        # Get name and namespace from metadata
        if metadata:
            name = _attr(metadata, 'name')
            namespace = _attr(metadata, 'namespace')
        else:
            name = None
            namespace = None

        # Build a minimal observer schema
        schema = {
            'apiVersion': api_version,
            'kind': kind,
            'metadata': {'name': name, 'namespace': namespace},
            'spec': spec
        }

        # Assign the schema back to the resource
        if isinstance(res, dict):
            res['observer_schema'] = schema
        else:
            setattr(res, 'observer_schema', schema)<|return|>

