        # If a string path is supplied, use the os module to inspect the filesystem
        if isinstance(path, str):
            if not os.path.isdir(path):
                return False
            ocfl_dir = os.path.join(path, '.ocfl')
            if not os.path.isdir(ocfl_dir):
                return False
            if not os.path.isdir(os.path.join(ocfl_dir, 'root')):
                return False
            if not os.path.isfile(os.path.join(ocfl_dir, 'desc')):
                return False

        # Otherwise assume a pyfilesystem2 object (or any object with the FS API)
        else:
            if not path.isdir('.ocfl'):
