        if isinstance(entry, dict):
            digest = entry.get('digest')
        else:
            digest = getattr(entry, 'digest', None)
        if digest is None:
            digest_missing_files.append(file_name)
        else:
            manifest_digests.add(digest)

    # convert digests_used to a set (if it is not already).  It may be a set, list, or tuple.
    digests_used_set = set(digests_used)

    # Digests listed as used but not found in the manifest
    digests_unused_in_manifest = digests_used_set - manifest_digests

    # Digests present in the manifest but not used anywhere
    digests_in_manifest_unused = manifest_digests - digests_used_set

    # Aggregate all problems that are found
    problems = []

    if digest_missing_files:
        problems.append(
            "Manifest entries missing a digest: "
            + ", ".join(sorted(digest_missing_files))
        )

    if digests_unused_in_manifest:
        problems.append(
            "Digests used but not present in the manifest: "
            + ", ".join(sorted(digests_unused_in_manifest))
        )

    if digests_in_manifest_unused:
        problems.append(
            "Digests present in the manifest but not used: "
            + ", ".join(sorted(digests_in_manifest_unused))
        )

    if problems:
        raise RuntimeError("; ".join(problems))<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # collect all digests expected from the manifest
    expected_digests = set()
    missing_files = []
    for file_name, digest in manifest_files.items():
        expected_digests.add(digest)
        if digest not in digests_used:
            missing_files.append(file_name)

    if missing_files:
        raise ValueError(
            f"Digests for the following files are missing from used digests: "
            f"{', '.join(missing_files)}"
        )

    # also verify that every used digest exists in the manifest
    unexpected_digests = digests_used - expected_digests
    if unexpected_digests:
        raise ValueError(
            f"Used digests not found in the manifest: "
            f"{', '.join(unexpected_digests)}"
        )

    return True<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    assert isinstance(prior, InventoryValidator)

    # Ensure both validators expose a version attribute and that prior is older
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("Both InventoryValidator objects must expose a 'version' attribute.")
    if prior.version >= self.version:
        raise ValueError(
            f"Prior inventory (version {prior.version}) must be older than current inventory (version {self.version})."
        )

    # Verify that the underlying inventory roots match
    current_root = getattr(self, "inventory", None)
    prior_root = getattr(prior, "inventory", None)
    if current_root is None or prior_root is None:
        raise AttributeError("Both InventoryValidator objects must have an 'inventory' attribute.")
    if getattr(current_root, "tag", None) != getattr(prior_root, "tag", None):
        raise ValueError(
            f"Root element mismatch: current has {getattr(current_root, 'tag', 'unknown')}, "
            f"prior has {getattr(prior_root, 'tag', 'unknown')}."
        )

    # Optional: ensure unique identifiers align if present
    if hasattr(self, "id") and hasattr(prior, "id") and self.id != prior.id:
        raise ValueError(
            f"Inventory IDs differ: current id={self.id}, prior id={prior.id}."
        )<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure the version can be compared numerically if possible
    try:
        cmp_version = int(version)
    except Exception:
        cmp_version = version

    path_map = {}

    # Inventory is expected to be a mapping: logical_path -> list of file entries
    for logical_path, entries in inventory.items():
        # Skip if entries is not iterable
        if not hasattr(entries, "__iter__"):
            continue

        content_set = set()
        for entry in entries:
            # Extract version for this entry; fallback to None if missing
            entry_version = entry.get("version") if isinstance(entry, dict) else None

            # Compare versions if possible
            if entry_version is None:
                continue
            try:
                entry_cmp = int(entry_version)
                matches = entry_cmp >= cmp_version
            except Exception:
                # If comparison fails use string comparison
                matches = entry_version >= cmp_version

            if matches:
                # Get the content file path; fallback to the entry itself if not a dict
                content_file = entry.get("content_file") if isinstance(entry, dict) else entry
                if content_file is not None:
                    content_set.add(content_file)

        if content_set:
            path_map[logical_path] = content_set

    return path_map<|return|>

