def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    # Assume inventory is a mapping from logical_path to a sub-mapping of
    # version -> content_file.  Content files may be a single filepath or a
    # collection of filepaths.
    path_map = {}
    for logical_path, ver_map in inventory.items():
        # If ver_map is not a mapping, skip it.
        if not isinstance(ver_map, dict):
            continue
        files = set()
        for ver, content_file in ver_map.items():
            # Compare versions (numeric or comparable)
            try:
                if ver >= version:
                    if isinstance(content_file, (set, list, tuple)):
                        files.update(content_file)
                    else:
                        files.add(content_file)
            except TypeError:
                # Unsupported version type; fallback to string comparison
                if str(ver) >= str(version):
                    if isinstance(content_file, (set, list, tuple)):
                        files.update(content_file)
                    else:
                        files.add(content_file)
        if files:
            path_map[logical_path] = files
    return path_map<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    mapping = {}
    # Expect inventory to be a mapping of version -> state mapping where each
    # state is a mapping of logical_path -> iterable of file names.
    for ver, state in inventory.items():
        # Skip older versions; versions should support ordering.
        try:
            if ver < version:
                continue
        except TypeError:
            if str(ver) < str(version):
                continue
        for logical_path, files in state.items():
            if logical_path not in mapping:
                mapping[logical_path] = set()
            mapping[logical_path].update(files)
    return mapping<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if 'file' not in fixity:
        raise ValueError("Missing 'file' key in fixity block.")
    files = fixity['file']
    if not isinstance(files, list):
        raise ValueError("'file' entry in fixity block must be a list.")
    # Prepare a set of manifest filenames for quick lookup
    manifest_set = set(manifest_files)
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary.")
        # name is required
        if 'name' not in entry:
            raise ValueError("File entry missing required 'name' field.")
        name = entry['name']
        if not isinstance(name, str):
            raise ValueError("File 'name' must be a string.")
        # Ensure the file exists in the manifest
        if name not in manifest_set:
            raise ValueError(f"File '{name}' referenced in fixity block is not present in the manifest.")
        # Optional fields: size and checksum (basic type checks)
        if 'size' in entry:
            size = entry['size']
            if not isinstance(size, int):
                raise ValueError(f"Size for file '{name}' must be an integer.")
        if 'checksum' in entry:
            checksum = entry['checksum']
            if not isinstance(checksum, str):
                raise ValueError(f"Checksum for file '{name}' must be a string.")
    # All entries validated successfully
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dict")
    # Expect a 'files' key containing a list of file descriptors
    files = fixity.get('files')
    if files is None:
        raise ValueError("Fixity block is missing the required 'files' key")
    if not isinstance(files, list):
        raise TypeError("'files' must be a list")

    for i, f in enumerate(files):
        if not isinstance(f, dict):
            raise TypeError(f"Each entry in 'files' must be a dict (entry {i})")
        path = f.get('path')
        checksum = f.get('checksum')
        # Some implementations might use 'ref' instead of 'path'
        if path is None and f.get('ref') is None:
            raise ValueError(f"File entry at index {i} lacks a 'path' (or 'ref') attribute")
        if checksum is None:
            raise ValueError(f"File entry at index {i} missing required 'checksum' attribute")

        file_key = path if path is not None else f['ref']
        if file_key not in manifest_files:
            raise ValueError(f"Reference to file '{file_key}' in fixity not present in manifest")
    # If we reach here everything is valid
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure that the fixity block is a dictionary or a list of (file, hash) pairs
    if isinstance(fixity, dict):
        entries = list(fixity.items())
    elif isinstance(fixity, (list, tuple)):
        # Expecting each element to be a (file_id, hash) tuple
        if not all(isinstance(e, (list, tuple, tuple)) and len(e) == 2 for e in fixity):
            raise ValueError("Fixity must be a dict or a list of (file, hash) tuples")
        entries = [(file_id, hash_val) for file_id, hash_val in fixity]
    else:
        raise ValueError("Fixity must be a dict or a list of (file, hash) tuples")

    # Turn the provided manifest file list into a set for efficient lookup
    manifest_set = set(manifest_files)

    # Loop over each entry in the fixity block to validate
    for file_id, hash_val in entries:
        if file_id not in manifest_set:
            raise ValueError(f"Fixity refers to unknown file '{file_id}'.")
        if not isinstance(hash_val, str):
            raise ValueError(f"Hash value for file '{file_id}' must be a string.")
        if not hash_val:
            raise ValueError(f"Hash value for file '{file_id}' cannot be empty.")
    # If all checks pass, return True (or simply pass if no return required)
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Normalise the list of manifest files to a set for fast lookup
        manifest_set = set(manifest_files)

        # Ensure the fixity block is a list; if it is a dict with a 'files' key,
        # use that list instead.
        if isinstance(fixity, dict):
            if 'files' not in fixity:
                raise ValueError("Fixity dict must contain a 'files' key")
            entries = fixity['files']
        else:
            entries = fixity

        if not isinstance(entries, list):
            raise ValueError("Fixity block must be a list (or dict containing a 'files' list)")

        seen_files = set()
        for i, entry in enumerate(entries):
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry {i} is not a dictionary")

            # Basic required fields
            for key in ('file', 'checksum'):
                if key not in entry:
                    raise ValueError(f"Fixity entry {i} missing required '{key}' field")

            fpath = entry['file']
            if fpath not in manifest_set:
                raise ValueError(f"Fixity entry {i} references unknown file '{fpath}'")

            if fpath in seen_files:
                raise ValueError(f"Duplicate fixity entry for file '{fpath}'")
            seen_files.add(fpath)

        # All checks passed; no return value needed
        return None<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise TypeError("manifest_files must be an iterable of file names")

    # Converting manifest to set for fast lookup
    manifest_set = set(manifest_files)

    # Validate each entry in the fixity block
    for fname, value in fixity.items():
        if not isinstance(fname, str):
            raise TypeError(f"Unexpected key type {type(fname).__name__} for file '{fname}'. Expected string.")
        if not isinstance(value, str):
            raise TypeError(f"Fixity value for '{fname}' must be a string, got {type(value).__name__}")
        if fname not in manifest_set:
            raise ValueError(f"File '{fname}' referenced in fixity block but not present in manifest")

    # Optional: check that the fixity block is not empty
    if not fixity:
        raise ValueError("Fixity block is empty")

    return True

