def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = " " * indent
    # Start opening tag
    parts = [f"{indent_str}<{self.__class__.__name__}"]
    # Include attributes if they exist
    if hasattr(self, "attributes") and isinstance(self.attributes, dict):
        for name, value in self.attributes.items():
            parts.append(f' {name}="{value}"')
    parts.append(">")
    # Render child elements recursively, if any
    if hasattr(self, "children") and isinstance(self.children, (list, tuple)):
        for child in self.children:
            if hasattr(child, "pretty") and callable(child.pretty):
                parts.append("\n" + child.pretty(indent + 2, debug))
            else:
                parts.append(f"\n{' ' * (indent + 2)}{child}")
    # Closing tag
    parts.append(f"\n{indent_str}</{self.__class__.__name__}>")
    result = "".join(parts)
    if debug:
        print(result)
    return result<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * (indent * 4)
    line = f"{indent_str}{self.__class__.__name__}"
    # Include an 'id' attribute if present
    if hasattr(self, "id") and self.id:
        line += f" id='{self.id}'"
    # Include other simple attributes
    for k, v in getattr(self, "__dict__", {}).items():
        if k in ("id", "_parent", "_doc"):
            continue
        if isinstance(v, (str, int, float)):
            line += f" {k}='{v}'"
    result = line
    # Recursively pretty-print children
    for child in self:
        result += "\n" + child.pretty(indent + 1, debug)
    return result<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    parts = []
    spacer = '  ' * indent
    # Opening tag with class name
    parts.append(f"{spacer}<{self.__class__.__name__}")
    # Include attributes if present
    if hasattr(self, "attributes"):
        for k, v in getattr(self, "attributes", {}).items():
            parts.append(f' {k}="{v}"')
    # Include id attribute if present
    if hasattr(self, "id") and self.id:
        parts.append(f' id="{self.id}"')
    # Debug information
    if debug:
        parts.append(f' debug="{id(self)}"')
    parts.append('>')
    # Include text content if present
    if hasattr(self, "text") and self.text:
        parts.append(self.text)
    # Recursively pretty print child elements
    if hasattr(self, "__iter__"):
        for child in self:
            if hasattr(child, "pretty"):
                parts.append('\n' + child.pretty(indent + 1, debug))
            else:
                parts.append(f'\n{spacer}  {repr(child)}')
    # Closing tag
    parts.append(f"\n{spacer}</{self.__class__.__name__}>")
    return ''.join(parts)<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions ------------------------------------------------------
    def is_op(expr, op_name):
        """Return True if expr represents the binary operator `op_name`."""
        return getattr(expr, 'op', None) == op_name

