        _recurse(self)
        return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure the storage root attribute exists
    if not hasattr(self, "root"):
        raise AttributeError("Instance has no 'root' attribute")
    root_path = self.root

    # Convert to absolute path if necessary
    try:
        root_path = os.path.abspath(root_path)
    except Exception:
        # If self.root is already a Path-like object
        pass

    if os.path.exists(root_path):
        if not os.path.isdir(root_path):
            raise OSError(f"'{root_path}' exists but is not a directory")
        # Check that the directory is empty (new root expected to be empty)
        if os.listdir(root_path):
            raise OSError(f"Storage root directory '{root_path}' must be empty; found contents")
    else:
        # Create the root directory
        os.makedirs(root_path, exist_ok=True)

    # Optionally create default subdirectories (commonly used in OCFL)
    # This is optional; adjust as needed for your implementation.
    for subdir in ("objects", "index"):
        sub_path = os.path.join(root_path, subdir)
        if not os.path.exists(sub_path):
            os.makedirs(sub_path, exist_ok=True)

    # Mark the root as initialized
    self.oid = None
    self._content_tree = None  # or whatever internal state is required

    return None<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError(f"Expected str, got {type(version).__name__}")
    if not version.isdigit():
        raise ValueError("Version must contain only digits")
    incremented = int(version) + 1
    if version.startswith('0'):
        # Preserve zero-padding width unless it overflows
        width = len(version)
        formatted = f"{incremented:0{width}d}"
        # If the increment forced an extra digit (e.g., 099 -> 100),
        # drop the leading zeros to keep the natural numbering scheme.
        if len(formatted) > width:
            formatted = str(incremented)
        return formatted
    else:
        return str(incremented)<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return '1'
    parts = version.split('.')
    # Find the last numeric segment
    for i in range(len(parts) - 1, -1, -1):
        seg = parts[i]
        if seg.isdigit():
            num = int(seg)
            new_num = num + 1
            # Preserve zero padding if present
            width = len(seg)
            if width > len(str(new_num)):
                new_seg = str(new_num).zfill(width)
            else:
                new_seg = str(new_num)
            parts[i] = new_seg
            return '.'.join(parts)
    # If no purely numeric segment was found, just append 1
    return version + '.1'<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version.isdigit():
        raise ValueError("version must be a numeric string")
    next_int = int(version) + 1
    if len(version) > 1 and version[0] == '0':
        return f"{next_int:0{len(version)}d}"
    else:
        return str(next_int)<|return|>

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os
        import json

        # Record differences: {version_dir: {file: (root_digest, version_digest)}}
        self._diff_digests = {}

        # Ensure we have a root inventory to compare against.  If not already loaded,
        # try to load it from a file named ``inventory.json`` in the root directory.
        if not hasattr(self, "root_inventory") or not self.root_inventory:
            root_inventory_path = os.path.join(self.root_dir, "inventory.json")
            if not os.path.isfile(root_inventory_path):
                raise FileNotFoundError(
                    f"Root inventory not found at {root_inventory_path}"
                )
            with open(root_inventory_path, "r", encoding="utf-8") as f:
                self.root_inventory = json.load(f)

        for vdir in version_dirs:
            inventory_path = os.path.join(vdir, "inventory.json")
            if not os.path.isfile(inventory_path):
                raise FileNotFoundError(
                    f"Inventory missing for version directory '{vdir}'. "
                    f"Expected file at {inventory_path}"
                )

            with open(inventory_path, "r", encoding="utf-8") as f:
                version_inventory = json.load(f)

            # Compare each digest in the version inventory against the root.
            diff_files = {}
            for fname, vdigest in version_inventory.get("digests", {}).items():
                root_digest = self.root_inventory.get("digests", {}).get(fname)
                if root_digest is None:
                    # The file is new in this version; that is acceptable
                    # but note it
                    diff_files[fname] = ("<new>", vdigest)
                elif root_digest != vdigest:
                    diff_files[fname] = (root_digest, vdigest)

            if diff_files:
                self._diff_digests[vdir] = diff_files

        return self._diff_digests<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not os.path.exists(path):
        return "not found"

    if os.path.isfile(path):
        name = os.path.basename(path)
        if not re.match(r"^0=", name):
            return "not a Namaste file"
        if name == "0=inventory":
            return "file"
        else:
            return f"unknown namaste file {name}"

    # path is a directory
    try:
        entries = os.listdir(path)
    except Exception as exc:
        return f"error: {exc!s}"

    namaste_files = [e for e in entries if re.match(r"^0=", e)]
    if not namaste_files:
        return "no Namaste file found"
    if len(namaste_files) > 1:
        return "multiple Namaste files found"

    fn = namaste_files[0]
    if fn == "0=storage":
        return "root"
    if fn == "0=object":
        return "object"
    if fn == "0=inventory":
        return "file"
    return f"unknown namaste file {fn}"<|return|>

