def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, MappingNode|Node) tuples.

    If a key appears multiple times, the corresponding MappingNode values are
    recursively merged; otherwise the last value wins.
    """
    # Helper to merge two lists of mapping children
    def _merge_children(children1, children2):
        # Convert to dict keyed by scalar value
        dict1 = {k.value: (k, v) for k, v in children1}
        dict2 = {k.value: (k, v) for k, v in children2}
        result = {}
        for key in set(dict1) | set(dict2):
            if key in dict1 and key in dict2:
                v1 = dict1[key][1]
                v2 = dict2[key][1]
                k2 = dict2[key][0]  # use second key node (last)
                if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
                    merged = MappingNode(tag=v2.tag, value=_merge_children(v1.value, v2.value))
                    result[key] = (k2, merged)
                else:
                    result[key] = (k2, v2)
            elif key in dict2:
                result[key] = dict2[key]
            else:
                result[key] = dict1[key]
        return list(result.values())

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                merged_children = _merge_children(existing_value_node.value, value_node.value)
                merged_value = MappingNode(tag=value_node.tag, value=merged_children)
                merged[key] = (existing_key_node, merged_value)
            else:
                # last wins
                merged[key] = (key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def merge_nodes(v1, v2):
        # If both are MappingNodes, recursively merge their contents
        if isinstance(v1, ruamel.yaml.nodes.MappingNode) and isinstance(v2, ruamel.yaml.nodes.MappingNode):
            # Build maps keyed by the scalar string value of each key node
            map1 = {k.value: (k, v) for k, v in v1.value}
            map2 = {k.value: (k, v) for k, v in v2.value}

            # Combine the keys, preserving order: keys from v1 first, then any new keys from v2
            combined_keys = []
            for k in map1:
                combined_keys.append(k)
            for k in map2:
                if k not in combined_keys:
                    combined_keys.append(k)

            merged_items = []
            for k in combined_keys:
                if k in map1 and k in map2:
                    # Recursively merge the two child nodes
                    new_val = merge_nodes(map1[k][1], map2[k][1])
                    merged_items.append((map1[k][0], new_val))
                elif k in map1:
                    merged_items.append((map1[k][0], map1[k][1]))
                else:
                    merged_items.append((map2[k][0], map2[k][1]))

            return ruamel.yaml.nodes.MappingNode(
                tag=v1.tag,
                value=merged_items,
                start_mark=v1.start_mark,
                end_mark=v1.end_mark,
            )
        else:
            # If they are not both MappingNodes, the latter value wins
            return v2

    merged = {}
    key_nodes = {}
    for key_node, value_node in nodes:
        # Assume key_node is a ScalarNode; use its value string as the key
        key = key_node.value
        if key in merged:
            merged[key] = merge_nodes(merged[key], value_node)
        else:
            merged[key] = value_node
            key_nodes[key] = key_node

    # Preserve the order of first occurrence of each key
    result = [(key_nodes[k], merged[k]) for k in key_nodes]
    return result<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to deep merge two MappingNode instances
    def merge_mapping(map1, map2):
        # map1, map2 are ruamel.yaml.nodes.MappingNode
        merged_pairs = []
        existing = {}
        order = []

        def add_pairs(m):
            for k_node, v_node in m.value:
                k = k_node.value
                if k not in existing:
                    order.append(k)
                    existing[k] = (k_node, v_node)
                else:
                    exist_k_node, exist_v_node = existing[k]
                    if (isinstance(exist_v_node, ruamel.yaml.nodes.MappingNode) and
                        isinstance(v_node, ruamel.yaml.nodes.MappingNode)):
                        merged_v = merge_mapping(exist_v_node, v_node)
                        existing[k] = (exist_k_node, merged_v)
                    else:
                        existing[k] = (exist_k_node, v_node)

        add_pairs(map1)
        add_pairs(map2)

        merged_pairs = [(existing[k][0], existing[k][1]) for k in order]
        # Preserve tag from the first mapping node
        return ruamel.yaml.nodes.MappingNode(map1.tag, merged_pairs, flow_style=map1.flow_style, value_style=map1.value_style)

    key_nodes = {}
    merged_values = {}
    order = []

    for key_node, value_node in nodes:
        key_val = key_node.value
        if key_val not in merged_values:
            order.append(key_val)
            key_nodes[key_val] = key_node

        if key_val in merged_values:
            existing_val = merged_values[key_val]
            if (isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and
                isinstance(value_node, ruamel.yaml.nodes.MappingNode)):
                merged_val = merge_mapping(existing_val, value_node)
                merged_values[key_val] = merged_val
            else:
                # last value wins
                merged_values[key_val] = value_node
        else:
            merged_values[key_val] = value_node

    return [(key_nodes[k], merged_values[k]) for k in order]<|return|>

