def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def is_mapping_node(node):
        return getattr(node, 'tag', None) is not None and \
               getattr(node, 'value', None) is not None and \
               isinstance(node.value, list)

    def merge_mapping_node(map1, map2):
        # map1 and map2 are MappingNode instances
        tag = map1.tag
        list1 = map1.value
        list2 = map2.value
        # build dictionaries of key string to (key_node, value_node)
        def build_dict(lst):
            d = {}
            for k_node, v_node in lst:
                d[k_node.value] = (k_node, v_node)
            return d
        dict1 = build_dict(list1)
        dict2 = build_dict(list2)
        merged_dict = {}
        merged_list = []
        # union of keys
        all_keys = set(dict1.keys()) | set(dict2.keys())
        for key in sorted(all_keys):  # sorted for stable order
            if key in dict1 and key in dict2:
                k1, v1 = dict1[key]
                k2, v2 = dict2[key]
                # choose key node from first occurrence
                key_node = k1
                if is_mapping_node(v1) and is_mapping_node(v2):
                    merged_value = merge_mapping_node(v1, v2)
                else:
                    # last wins: take v2
                    merged_value = v2
                merged_list.append((key_node, merged_value))
            elif key in dict1:
                merged_list.append(dict1[key])
            else:
                merged_list.append(dict2[key])
        # create new mapping node
        MappingNode = type(map1)
        return MappingNode(tag, merged_list)

    result = {}
    key_to_node = {}
    ordering = []
    for key_node, val_node in nodes:
        key = key_node.value
        if key not in result:
            ordering.append(key)
            key_to_node[key] = key_node
            result[key] = val_node
        else:
            existing = result[key]
            if is_mapping_node(existing) and is_mapping_node(val_node):
                result[key] = merge_mapping_node(existing, val_node)
            else:
                # last wins
                result[key] = val_node

    # build the output list preserving the order of first appearance
    merged_nodes = [(key_to_node[k], result[k]) for k in ordering]
    return merged_nodes<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    def merge_mapping_nodes(m1, m2):
        # Create a mapping from key value to (key_node, value_node) for m1
        existing = {k_node.value: v_node for k_node, v_node in m1.value}
        # Update with m2, merging recursively if necessary
        for k_node2, v_node2 in m2.value:
            k = k_node2.value
            if k in existing:
                v1 = existing[k]
                if isinstance(v1, MappingNode) and isinstance(v_node2, MappingNode):
                    existing[k] = merge_mapping_nodes(v1, v_node2)
                else:
                    existing[k] = v_node2
            else:
                existing[k] = v_node2
        # Build new value list preserving order: first from m1, then any new keys from m2
        new_value = []
        m1_keys = [k_node.value for k_node, _ in m1.value]
        for k_node, _ in m1.value:
            k = k_node.value
            new_value.append((k_node, existing[k]))
        for k_node, _ in m2.value:
            k = k_node.value
            if k not in m1_keys:
                new_value.append((k_node, existing[k]))
        return MappingNode(m1.tag, new_value)

    merged = {}
    order = []
    for key_node, value in nodes:
        k = key_node.value
        if k in merged:
            existing_key_node, existing_value = merged[k]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                merged_value = merge_mapping_nodes(existing_value, value)
                merged[k] = (existing_key_node, merged_value)
            else:
                merged[k] = (existing_key_node, value)
        else:
            order.append(k)
            merged[k] = (key_node, value)
    return [(merged[k][0], merged[k][1]) for k in order]<|return|>

