def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    # Flatten the argument list
    args = []
    for arg in unparsed_arguments:
        if isinstance(arg, (list, tuple)):
            args.extend(arg)
        else:
            args.append(arg)

    result = {}
    current_name = "global"
    current_list = []

    i = 0
    while i < len(args):
        token = args[i]
        # Determine if token is a subparser name (not an option)
        if token.startswith("-"):
            # Option flag
            current_list.append(token)
            # Attempt to consume the next element as a value if it is not an option
            if i + 1 < len(args) and not args[i + 1].startswith("-"):
                current_list.append(args[i + 1])
                i += 1
        else:
            # New subparser encountered
            if current_list:
                # Parse the accumulated arguments for the previous subparser
                parser = argparse.ArgumentParser(add_help=False)
                namespace, _ = parser.parse_known_args(current_list)
                result[current_name] = namespace
            current_name = token
            current_list = []
        i += 1

    # Parse the final segment
    if current_list:
        parser = argparse.ArgumentParser(add_help=False)
        namespace, _ = parser.parse_known_args(current_list)
        result[current_name] = namespace

    return result<|return|>

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    import re

    if not isinstance(size, str):
        raise ValueError("size must be a string")

    size = size.strip()
    match = re.match(r"^([\d\.]+)\s*([KMGT]?)$", size, re.IGNORECASE)
    if not match:
        raise ValueError(f"Invalid size format: {size!r}")

    number, unit = match.groups()
    try:
        num = float(number)
    except ValueError:
        raise ValueError(f"Invalid number in size: {number!r}")

    multiplier = 1
    if unit:
        unit = unit.upper()
        if unit == "K":
            multiplier = 10**3
        elif unit == "M":
