def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Detect platform if needed
    if platform == 'this':
        if sys.platform.startswith(('win32', 'cygwin', 'msys')):
            platform = 0
        else:
            platform = 1

    # POSIX: use a simple regex to split quoted and unquoted tokens
    if platform == 1:
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''')
        parts = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                parts.append(m.group(1))
            elif m.group(2) is not None:
                parts.append(m.group(2))
            else:
                parts.append(m.group(3))
        return parts

    # Windows: a lightweight parser that mimics CMD parsing rules
    if platform == 0:
        tokens = []
        current = []
        inquote = False
        i = 0
        length = len(s)
        while i < length:
            ch = s[i]
            if inquote:
                if ch == '\\':
                    # Count consecutive backslashes before a quote
                    bs_count = 1
                    i += 1
                    while i < length and s[i] == '\\':
                        bs_count += 1
                        i += 1
                    if i < length and s[i] == '"':
                        # Even number of backslashes -> half are escapes for quotes
                        current.extend(['\\'] * (bs_count // 2))
                        if bs_count % 2 == 1:
                            current.append('"')
                        else:
                            # This backslash escapes the quote
                            # don't add the quote itself
                            pass
                        i += 1  # skip the quote
                        continue
                    else:
                        # No quote follows, all backslashes are literal
                        current.extend(['\\'] * bs_count)
                        continue
                elif ch == '"':
                    inquote = False
                else:
                    current.append(ch)
            else:
                if ch.isspace():
                    if current:
                        tokens.append(''.join(current))
                        current = []
                elif ch == '"':
                    inquote = True
                else:
                    current.append(ch)
            i += 1
        if current:
            tokens.append(''.join(current))
        return tokens

    # Reserved or unsupported platform value
    raise ValueError(f"Unsupported platform value: {platform}")<|return|>

