    elif unit in ('week', 'w'):
        kwargs['weeks'] = num
    elif unit in ('hour', 'h'):
        kwargs['hours'] = num
    elif unit in ('minute', 'min', 'm'):
        kwargs['minutes'] = num
    elif unit in ('second', 'sec', 's'):
        kwargs['seconds'] = num
    else:
        raise ValueError("Unknown time unit in frequency: %r" % unit)

    return datetime.timedelta(**kwargs)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    s = frequency.strip()
    if not s or s.lower() == 'always':
        return None

    parts = s.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    try:
        value = float(parts[0])
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: {frequency!r}")

    unit = parts[1].lower()
    if unit.startswith('day'):
        return datetime.timedelta(days=value)
    elif unit.startswith('week'):
        return datetime.timedelta(weeks=value)
    elif unit.startswith('hour'):
        return datetime.timedelta(hours=value)
    elif unit.startswith('minute'):
        return datetime.timedelta(minutes=value)
    elif unit.startswith('second'):
        return datetime.timedelta(seconds=value)
    else:
        raise ValueError(f"Unsupported unit in frequency: {frequency!r}")<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    local_identifiers = {"localhost", "127.0.0.1", "::1"}
    if host in local_identifiers:
        return True
    try:
        # Resolve the supplied host
        resolved_hosts = socket.gethostbyname_ex(host)[2]
        # Resolve the local machine
        local_hosts = socket.gethostbyname_ex(socket.gethostname())[2]
        return any(addr in local_hosts for addr in resolved_hosts)
    except socket.gaierror:
        return False<|return|>

