    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addr_info:
        ip = sockaddr[0]
        if family == socket.AF_INET and ip == '127.0.0.1':
            return True
        if family == socket.AF_INET6 and ip == '::1':
            return True

    # Handle simple localhost name
    return host == 'localhost'<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    if host in ('localhost', '127.0.0.1', '::1'):
        return True
    try:
        infos = socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        for info in infos:
            af, _, _, _, sockaddr = info
            if af == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith('127.'):
                    return True
            elif af == socket.AF_INET6:
                ip = sockaddr[0]
                if ip in ('::1', '0:0:0:0:0:0:0:1'):
                    return True
        return False
    except socket.error:
        return False<|return|>

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess, os, sys, textwrap, json
    wrapper = textwrap.dedent(f'''
        import sys
        import json
        from {func.__module__} import {func.__name__}
        try:
            result = {func.__name__}(*sys.argv[1:])
            print(json.dumps(result))
        except Exception as e:
            import traceback
            traceback.print_exc(file=sys.stderr)
            sys.exit(1)
    ''')
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    result = subprocess.run(
        [sys.executable, '-c', wrapper, *map(str, args)],
        capture_output=True,
        text=True,
        timeout=timeout,
        env=env
    )
    if result.returncode != 0:
        raise RuntimeError(f"Subprocess failed with exit code {result.returncode}:\n{result.stderr}")
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return result.stdout)<|return|>

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if isinstance(matcher, (tuple, list)):
        var_name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, str):
        var_name = matcher
        default = None
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    value = os.getenv(var_name)
    if value is not None:
