def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, logging, re, os
    configs = {}
    failures = []

    # regex to find ${VAR} placeholders
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env_strings(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_strings(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_strings(v) for v in obj]
        if isinstance(obj, str) and resolve_env:
            return env_pattern.sub(lambda m: os.environ.get(m.group(1), ''), obj)
        return obj

    for fn in config_filenames:
        try:
            with open(fn, 'r', encoding='utf-8') as fd:
                data = json.load(fd)
            # resolve environment variables if needed
            data = _resolve_env_strings(data)

            # apply overrides if provided
            if overrides and fn in overrides:
                if isinstance(overrides[fn], dict):
                    data.update(overrides[fn])

            # simple validation: ensure it's a dict
            if not isinstance(data, dict):
                raise ValueError('Configuration must be a top‑level JSON object')

            configs[fn] = data

        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fn,
                lineno=0,
                msg=f'Failed to load configuration {fn!r}: {exc}',
                args=(),
                exc_info=None
            )
            failures.append(record)

    return configs, failures<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed
    configuration, and sequence of logging.LogRecord instances containing any parse errors.

    Parameters
    ----------
    config_filenames : Iterable[str]
        Iterable of paths to configuration files.
    overrides : dict or None, optional
        Dictionary of key-value pairs to override in the parsed configuration.
    resolve_env : bool, optional
        If True, resolve environment variables in string values of the form ${VAR}.

    Returns
    -------
    tuple
        A tuple of (:class:`dict`, :class:`list`) where the dictionary maps each filename
        to the parsed configuration object (typically a :class:`dict`) and the list contains
        :class:`logging.LogRecord` objects for any errors encountered during loading.
    """
    import json
    import logging
    import os

    configs = {}
    error_records = []

    def resolve_env_vars(value):
        if not isinstance(value, str):
            return value
        output = value
        for var in os.environ:
            placeholder = f"${{{var}}}"
            if placeholder in output:
                output = output.replace(placeholder, os.environ[var])
        return output

    def recursively_process(obj):
        if isinstance(obj, dict):
            return {k: recursively_process(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [recursively_process(item) for item in obj]
        else:
            return resolve_env_vars(obj)

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
            # Attempt to parse as JSON; fall back to YAML if available.
            try:
                parsed = json.loads(content)
            except json.JSONDecodeError:
                # Try YAML if PyYAML is available
                try:
                    import yaml
                    parsed = yaml.safe_load(content)
                except Exception:
                    # Unsupported format
                    raise ValueError(f"Unsupported configuration format for file {fname}")
            if not isinstance(parsed, dict):
                raise ValueError(f"Configuration root must be a JSON/YAML object (dict) in file {fname}")

            if overrides:
                for key, val in overrides.items():
                    if key in parsed:
                        parsed[key] = val

            if resolve_env:
                parsed = recursively_process(parsed)

            configs[fname] = parsed

        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=True
            )
            error_records.append(record)

    return configs, error_records<|return|>

