def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return the current scale if no new value is supplied
    if other is None:
        return getattr(self, "_scale", None)

    # Validate the new scale
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric value")

    # Current scale must be known and non‑zero
    current_scale = getattr(self, "_scale", None)
    if not current_scale or current_scale == 0:
        raise LenaValueError("Graph has unknown or zero scale; cannot rescale")

    # Compute scaling factor
    factor = other / current_scale

    # Rescale the last coordinate of each data point
    points = getattr(self, "points", None)
    if points is not None:
        # Simple list-of‑tuples/list handling
        if isinstance(points, list):
            for i, p in enumerate(points):
                try:
                    new = list(p)
                    new[-1] *= factor
                    points[i] = new
                except Exception:
                    # If point format is unexpected, skip
                    pass
        # NumPy array support (optional)
        elif hasattr(points, "__setitem__"):
            try:
                points[..., -1] *= factor
            except Exception:
                pass

    # Rescale errors in the same way, if present
    errors = getattr(self, "errors", None)
    if errors is not None:
        if isinstance(errors, list):
            for i, e in enumerate(errors):
                try:
                    new = list(e)
                    new[-1] *= factor
                    errors[i] = new
                except Exception:
                    pass
        elif hasattr(errors, "__setitem__"):
            try:
                errors[..., -1] *= factor
            except Exception:
                pass

    # Update and return
    self._scale = other
    return self
<|return|>

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    if make_value is None:
        make_value = lambda v: v

    # Try to get the list of bins; assume hist.bins or hist and iterating over it yields bins
    try:
        bins = hist.bins
    except AttributeError:
        bins = iter(hist)

    points = []
    for b in bins:
        # Get the content. Try common attributes
        content = None
        try:
            content = b.content
        except AttributeError:
            try:
                content = b.values
            except AttributeError:
                # assume the bin itself is the value
                content = b

        try:
            val = make_value(content)
        except Exception as e:
            raise ValueError(f"make_value failed for bin content {content!r}: {e}") from e

        # Compute coordinate
        if get_coordinate == "left":
            try:
                coord = b.left
            except AttributeError:
                try:
                    coord = b.low
                except AttributeError:
                    raise AttributeError("Cannot determine left coordinate of bin") from None
        elif get_coordinate == "right":
            try:
                coord = b.right
            except AttributeError:
                try:
                    coord = b.high
                except AttributeError:
                    raise AttributeError("Cannot determine right coordinate of bin") from None
        elif get_coordinate == "middle":
            try:
                coord = (b.left + b.right) / 2
            except AttributeError:
                try:
                    coord = (b.low + b.high) / 2
                except AttributeError:
                    raise AttributeError("Cannot determine middle coordinate of bin") from None
        else:
            raise ValueError(f"Invalid get_coordinate value: {get_coordinate!r}")

        # Prepare point record
        if isinstance(val, (tuple, list)):
            if len(field_names) - 1 != len(val):
                raise ValueError("Number of field names does not match returned value size")
            point_data = dict(zip(field_names, (coord, ) + tuple(val)))
        else:
            if len(field_names) != 2:
                raise ValueError("field_names must be two elements for scalar value")
            point_data = {field_names[0]: coord, field_names[1]: val}

        points.append(point_data)

    # Determine scale
    graph_scale = None
    if scale is True:
        try:
            graph_scale = getattr(hist, "scale", None)
        except AttributeError:
            graph_scale = None
    elif scale is not None:
        graph_scale = scale

    graph = {"points": points, "scale": graph_scale}
    return graph<|return|>

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface.interface import InterfaceClass
    from zope.interface import Invalid

    # 1. Make sure the candidate claims to provide the interface
    if not tentative:
        try:
            # iface.providedBy returns bool
            if not iface.providedBy(candidate):
                raise Invalid(
                    f"Candidate {candidate!r} does not claim to provide {iface!r}"
                )
        except Exception as exc:
            # In case iface.providedBy does not exist (older zope)
            # we fall back to manual check of implements/ provides
            impl = getattr(candidate.__class__, '__implementer__', None)
            if not impl or iface not in impl:
                raise Invalid(
                    f"Candidate {candidate!r} does not claim to provide {iface!r}"
                ) from exc

    errors = []

    # Helper to compare signatures
    def compare_signature(expected, actual, opname):
        try:
            sig_expected = inspect.signature(expected)
            sig_actual = inspect.signature(actual)
        except (ValueError, TypeError):
            # Unable to introspect; skip comparison
            return
        # Compare parameters by name and kind
        eps = sig_expected.parameters
        aps = sig_actual.parameters
        if len(eps) != len(aps):
            errors.append(
                f"Method '{opname}' signature mismatch: expected {len(eps)} "
                f"params, got {len(aps)}"
            )
            return
        for (e_name, e_param), (a_name, a_param) in zip(eps.items(), aps.items()):
            if e_name != a_name:
                errors.append(
                    f"Method '{opname}' parameter name mismatch: expected '{e_name}', got '{a_name}'"
                )
            if e_param.kind != a_param.kind:
                errors.append(
                    f"Method '{opname}' parameter kind mismatch for '{e_name}': "
                    f"expected {e_param.kind}, got {a_param.kind}"
                )
        # Compare return annotation if present
        if sig_expected.return_annotation != inspect.Signature.empty:
            if sig_actual.return_annotation != inspect.Signature.empty:
                if sig_expected.return_annotation != sig_actual.return_annotation:
                    errors.append(
                        f"Method '{opname}' return type mismatch: "
                        f"expected {sig_expected.return_annotation}, got {sig_actual.return_annotation}"
                    )
            else:
                errors.append(
                    f"Method '{opname}' missing return annotation, expected {sig_expected.return_annotation}"
                )

    # 2. Check methods and attributes defined by the interface
    #   a) Operations (methods)
    try:
        op_names = iface.getOperationNames()
    except AttributeError:
        # Fallback for older zope.interface
        op_names = [name for name in dir(iface) if callable(getattr(iface, name))]

    for opname in op_names:
        try:
            expected = iface.getOperation(opname)
        except KeyError:
            continue
        actual = getattr(candidate, opname, None)
        if actual is None:
            errors.append(f"Missing method '{opname}' required by {iface!r}")
            continue
        if not callable(actual):
            errors.append(f"Attribute '{opname}' is not callable on {candidate!r}")
            continue
        compare_signature(expected, actual, opname)

    #   b) Variables (attributes)
    try:
        vars_dict = iface.variables()
    except AttributeError:
        # older version may use `variables` method
        vars_dict = {}
    for varname, vartype in vars_dict.items():
        if not hasattr(candidate, varname):
            errors.append(f"Missing attribute '{varname}' required by {iface!r}")

        # If vartype is defined, optionally check type
        # (we can't rely on types in many cases, so skip strict type checking)

    # 3. Raise collected errors or return True
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))
    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if candidate is None:
        return False

    is_cls = isinstance(candidate, type)

    if tentative:
        if is_cls:
            return issubclass(candidate, iface)
        return isinstance(candidate, iface)

    # Full verification
    if is_cls:
        if not issubclass(candidate, iface):
            raise TypeError(f"Candidate class {candidate!r} does not subclass interface {iface}")
        # Retrieve abstract methods defined by the interface, if any
        required = getattr(iface, "__abstractmethods__", set())
    else:
        if not isinstance(candidate, iface):
            raise TypeError(f"Candidate {candidate!r} is not an instance of interface {iface}")
        required = getattr(iface, "__abstractmethods__", set())

    # Determine which required methods are missing from the candidate
    missing = required - set(dir(candidate))
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise TypeError(f"Candidate {candidate!r} does not implement abstract methods: {missing_str}")

    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Helper to fetch the required callable attributes of the interface
    def required_attrs(proto):
        return [
            name
            for name in dir(proto)
            if callable(getattr(proto, name)) and not name.startswith("_")
        ]

    # Candidate is a class
    if isinstance(candidate, type):
        if issubclass(candidate, iface):
            return True
        req = required_attrs(iface)
        for name in req:
            if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
                if tentative:
                    return False
                raise ValueError(
                    f"Candidate class {candidate.__name__} does not implement required method {name}"
                )
        return True

    # Candidate is an instance
    if isinstance(candidate, iface):
        return True
    req = required_attrs(iface)
    for name in req:
        if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
            if tentative:
                return False
            raise ValueError(
                f"Candidate instance {candidate} does not implement required method {name}"
            )
    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # If candidate is already an instance of iface
    if isinstance(candidate, iface):
        return True

    # Determine the class of the candidate
    cls = candidate if isinstance(candidate, type) else type(candidate)

    # Check for subclass relationship
    try:
        if issubclass(cls, iface):
            return True
    except TypeError:
        # cls is not a class; skip subclass check
        pass

    # Verify required attributes/methods defined on the interface
    for name in dir(iface):
        # Skip special/dunder attributes
        if name.startswith('__') and name.endswith('__'):
            continue
        if not hasattr(cls, name):
            if tentative:
                return False
            raise TypeError(
                f"Candidate {cls.__name__} does not provide "
                f"required attribute '{name}' for interface {iface.__name__}"
            )
    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it
    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        # Collect metaclasses from the bases (ignore the default 'type')
        base_mcls = type
        for b in bases:
            m = type(b)
            if m is not type:
                if base_mcls is type:
                    base_mcls = m
                else:
                    # Find a common super‑metaclass
                    for cls in base_mcls.mro():
                        if issubclass(m, cls):
                            base_mcls = cls
                            break
                    else:
                        raise TypeError(
                            f"Metaclass conflict: {m} is not a subclass of {base_mcls}"
                        )
        metaclass = base_mcls
    # Ensure all bases are subclasses of the chosen metaclass
    for b in bases:
        if not issubclass(b, metaclass):
            raise TypeError(
                f"Base {b} is not a subclass of the chosen metaclass {metaclass}"
            )
    return metaclass<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # use explicit metaclass if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a class")
        for base in bases:
            if base is not None:
                base_meta = type(base)
                if not issubclass(base_meta, explicit_mc):
                    raise TypeError(
                        "metaclass conflict: {} is not a subclass of explicit metaclass {}".format(
                            base_meta.__name__, explicit_mc.__name__
                        )
                    )
        return explicit_mc

    # derive metaclass from bases
    if not bases:
        return type

    metas = [type(b) for b in bases if b is not None]
    meta = metas[0]
    for m in metas[1:]:
        if issubclass(meta, m):
            continue
        elif issubclass(m, meta):
            meta = m
        else:
            raise TypeError(
                "metaclass conflict: {} is not a subclass of {}".format(meta.__name__, m.__name__)
            )
    return meta<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if not bases:
        raise ValueError("At least one base required to determine a metaclass.")

    # Use the explicit metaclass if provided, otherwise start from the first base's metaclass
    if explicit_mc is not None:
        candidate = explicit_mc
    else:
        candidate = type(bases[0])

    for base in bases:
        base_meta = type(base)
        if base_meta is candidate:
            # Same metaclass, nothing to change
            continue

        # Ensure the candidate is compatible with the base's metaclass
        if issubclass(candidate, base_meta):
            # Candidate is more specific, keep it
            continue
        if issubclass(base_meta, candidate):
            # Base's metaclass is more specific, adopt it
            candidate = base_meta
        else:
            # Incompatible metaclasses
            raise TypeError("metaclass conflict: %s and %s" %
                            (candidate.__name__, base_meta.__name__))

    return candidate<|return|>

