def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    # Determine the key with lowest frequency
    if hasattr(self, 'freq'):
        key = min(self.freq, key=lambda k: self.freq[k])
    else:
        # If no frequency tracking, just pick an arbitrary key
        key = min(self, key=lambda k: 0)
    value = self.pop(key)
    # Remove from frequency dict if present
    if hasattr(self, 'freq'):
        try:
            del self.freq[key]
        except KeyError:
            pass
    return key, value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem from an empty container")
    # Determine key with the lowest frequency
    try:
        key = min(self._freq, key=lambda k: self._freq[k])
    except AttributeError:
        # If no frequency tracking, fall back to arbitrary item
        key = next(iter(self))
    value = self[key]
    # Remove key from both data and frequency bookkeeping
    del self[key]
    if hasattr(self, "_freq"):
        self._freq.pop(key, None)
    return key, value<|return|>

