def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    """Parse the date/time string into a :class:`datetime.datetime` object."""

    # Ensure the input is a string
    if isinstance(timestr, (bytes, bytearray)):
        raise TypeError('cannot parse byte string')
    if not isinstance(timestr, str):
        try:
            timestr = str(timestr)
        except Exception as exc:
            raise TypeError(f'cannot parse {type(timestr).__name__}') from exc

    # Delegate parsing to the internal _parse function
    res = _parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)

    # _parse returns a tuple (datetime, tokens).  If parsing failed, datetime will be None
    dt, tokens = res
    if dt is None:
        raise ParserError('unknown string format')

    # If the caller requested fuzzy token output, return the tuple
    if kwargs.get('fuzzy_with_tokens'):
        return (dt, tokens)

    return dt<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Assume the request object may expose a ``type`` attribute or ``message_type``.
    # Check for public message first
    try:
        if getattr(request, "type", None) in ("public", "diaspora_public") or getattr(request, "message_type", None) in ("public", "diaspora_public"):
            return True
    except Exception:
        pass

    # Check for private message next
    try:
        if getattr(request, "type", None) in ("private", "diaspora_private") or getattr(request, "message_type", None) in ("private", "diaspora_private"):
            return True
    except Exception:
        pass

    # Finally, look for legacy payload indicators
    legacy_keys = ("legacy_payload", "is_legacy", "legacy", "diaspora_legacy")
    for key in legacy_keys:
        try:
            if getattr(request, key, False):
                return True
        except Exception:
            continue

    return False<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Attempt to detect a Diaspora request via known headers or payload markers.
    try:
        # First, check public message header
        if getattr(request, 'headers', None) and request.headers.get('X-Diaspora-Public') == 'true':
            return True
        # Then, check private message header
        if getattr(request, 'headers', None) and request.headers.get('X-Diaspora-Private') == 'true':
            return True
        # Finally, attempt to parse a legacy payload
        if hasattr(request, 'json'):
            data = request.json()
            if isinstance(data, dict) and data.get('payload_type') == 'diaspora':
                return True
    except Exception:
        pass
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # Attempt to determine if the request is for the Matrix API.
    # Many request objects expose a 'type' attribute or an explicit boolean flag.
    if hasattr(request, "is_matrix"):
        try:
            return bool(request.is_matrix)
        except Exception:
            pass
    if hasattr(request, "type"):
        try:
            return str(request.type).lower() == "matrix"
        except Exception:
            pass
    # Fallback: look for a typical Matrix-specific endpoint in the request URL.
    if hasattr(request, "url"):
        return "matrix" in request.url.split("?")[0].lower()
    # If none of the checks succeeded, we cannot determine.
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""

    try:
        # Check the request path; many Matrix APIs start with "/matrix"
        path = getattr(request, "path", None) or getattr(request, "url", None)
        if path and str(path).startswith("/matrix"):
            return True

        # Inspect headers that may indicate a Matrix request
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict) and any(key.lower() == "x-matrix-request" for key in headers):
            return True

        # Look for a "matrix" query parameter
        params = getattr(request, "query_params", None) or getattr(request, "params", None)
        if params:
            if "matrix" in params or params.get("matrix"):
                return True
    except Exception:
        # If anything goes wrong while inspecting the request, assume it's not a Matrix request
        return False

    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # Basic heuristic: check for typical Matrix request markers
    # 1. Look for a special Matrix header
    if hasattr(request, "headers"):
        header_keys = [k.lower() for k in request.headers] if isinstance(request.headers, dict) else []
        for key in ("matrix-request", "x-matrix-request"):
            if key in header_keys:
                return True
    # 2. Check the request path for a common Matrix endpoint prefix
    if hasattr(request, "path"):
        try:
            if request.path.lower().startswith("/matrix"):
                return True
        except Exception:
            pass
    # Fallback: not a Matrix request
    return False<|return|>

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    from datetime import datetime, date

    if isinstance(dt, datetime):
        # ISO 8601 format without microseconds
        return dt.strftime('%Y-%m-%dT%H:%M:%S')
    elif isinstance(dt, date):
        return dt.strftime('%Y-%m-%d')
    else:
        raise TypeError(f"Unsupported type {type(dt).__name__}: must be datetime or date")<|return|>

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    try:
        return dt.isoformat()
    except Exception as e:
        raise TypeError("dt must be a datetime or date object") from e<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    if dt is None:
        return None
    if isinstance(dt, datetime.datetime):
        dt = dt.replace(microsecond=0)
    elif isinstance(dt, datetime.date):
        dt = datetime.datetime.combine(dt, datetime.time.min)
    else:
        raise TypeError("dt must be a datetime or date instance")
    return dt.isoformat()<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=5) as resp:
            return resp.info().get('Content-Type')
    except Exception:
        return None<|return|>

