def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    # Helper to strip namespace
    def _local(tag: str) -> str:
        return tag.split("}")[1] if "}" in tag else tag

    result: Dict = {}
    # Subject
    subject_elem = root.find(lambda e: _local(e.tag) == "Subject")
    if subject_elem is not None and subject_elem.text:
        result["subject"] = subject_elem.text.strip()

    # Aliases
    aliases = [
        e.text.strip()
        for e in root.findall(lambda e: _local(e.tag) == "Alias")
        if e.text
    ]
    if aliases:
        result["aliases"] = aliases

    # Properties
    properties: Dict[str, str] = {}
    for e in root.findall(lambda e: _local(e.tag) == "Property"):
        rel = e.get("rel")
        if rel and e.text:
            properties[rel] = e.text.strip()
    if properties:
        result["properties"] = properties

    # Links
    links = []
    for e in root.findall(lambda e: _local(e.tag) == "Link"):
        href = e.get("href")
        rel = e.get("rel")
        if href:
            link_info = {"href": href}
            if rel:
                link_info["rel"] = rel
            links.append(link_info)
    if links:
        result["links"] = links

    return result
<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Helper to detect if text is JSON
    def _is_json(text: str) -> bool:
        text = text.strip()
        return text.startswith('{') or text.startswith('[')

    # Common return structure
    result: Dict = {}

    if _is_json(document):
        # New JSON format
        try:
            data = json.loads(document)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON WebFinger response: {exc}") from exc
        # Typically contains 'subject' and 'links'
        result['subject'] = data.get('subject')
        result['links'] = data.get('links', [])
        # Public key may be nested
        public_key = data.get('public_key', {})
        if public_key:
            result['public_key'] = public_key
        return result

    # Old XRD XML format
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML WebFinger response: {exc}") from exc

    namespace = ''
    if root.tag.startswith('{'):
        # Extract namespace if present
        namespace = root.tag.split('}')[0] + '}'

    # Subject
    subject_el = root.find(f'{namespace}Subject')
    if subject_el is None:
        raise ValueError("Missing <Subject> element in XRD WebFinger response")
    result['subject'] = subject_el.text

    # Public key
    pubkey_el = root.find(f'{namespace}PublicKey')
    if pubkey_el is not None:
        # The key is usually in a <RSAKey> or <DSAKey> sub-element
        result['public_key'] = {}
        for child in pubkey_el:
            result['public_key'][child.tag.replace(namespace, '')] = child.text

    # Links
    links = []
    for link_el in root.findall(f'{namespace}Link'):
        href = link_el.get('href')
        rel = link_el.get('rel')
        type_ = link_el.get('type')
        algorithm = link_el.get('algorithm')
        link_dict: Dict = {}
        if href:
            link_dict['href'] = href
        if rel:
            link_dict['rel'] = rel
        if type_:
            link_dict['type'] = type_
        if algorithm:
            link_dict['algorithm'] = algorithm
        links.append(link_dict)
    result['links'] = links

    return result<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    # First try JSON
    try:
        data = json.loads(document)
        # Most JSON webfinger responses already contain the needed fields.
        return data
    except Exception:
        # Assume XRD (RSS/Atom Description Language) format if JSON fails.
        try:
            root = ET.fromstring(document)
        except ET.ParseError as e:
            raise ValueError("Invalid webfinger document: could not parse as JSON or XML") from e

        # Namespace handling for XRD
        ns = {'xrd': 'xri://$xrd*($v*2.0)'}

        def ns_tag(tag):
            return f"{{{ns['xrd']}}}{tag}" if ns.get('xrd') else tag

        result = {}
        # Subject
        subject_el = root.find(ns_tag('Subject'))
        if subject_el is not None:
            result['subject'] = subject_el.text

        # Aliases
        aliases = [a.text for a in root.findall(ns_tag('Alias')) if a.text]
        if aliases:
            result['aliases'] = aliases

        # Links
        links = []
        for link_el in root.findall(ns_tag('Link')):
            link_dict = {}
            for attr in ['rel', 'type', 'href', 'title']:
                val = link_el.attrib.get(attr)
                if val:
                    link_dict[attr] = val
            # Include any other attributes if present
            for k, v in link_el.attrib.items():
                if k not in link_dict:
                    link_dict[k] = v
            if link_dict:
                links.append(link_dict)
        if links:
            result['links'] = links

        return result
<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    from collections import defaultdict

    # Try JSON first
    try:
        data = json.loads(document)
        # Ensure mandatory key
        if 'subject' in data:
            # Normalize aliases to list
            aliases = data.get('aliases', [])
            # Links can be list of dicts, transform to dict keyed by rel
            links = {}
            for link in data.get('links', []):
                rel = link.get('rel')
                href = link.get('href')
                if rel and href:
                    # Allow multiple links for same rel
                    links.setdefault(rel, []).append(href)
            return {
                'subject': data['subject'],
                'aliases': aliases,
                'links': links
            }
    except (json.JSONDecodeError, ValueError):
        pass  # fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        # Not valid XML either
        return {}

    ns = {'xrd': 'http://www.w3.org/2005/11/Authentication'}
    subject_el = root.find('xrd:Subject', ns)
    if subject_el is None:
        return {}

    subject = subject_el.text or ''
    aliases = [a.text for a in root.findall('xrd:Alias', ns) if a.text]
    link_elems = root.findall('xrd:Link', ns)
    links = defaultdict(list)
    for link in link_elems:
        rel = link.get('rel')
        href = link.get('href')
        if rel and href:
            links[rel].append(href)

    return {
        'subject': subject,
        'aliases': aliases,
        'links': dict(links)
    }<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Parse the handle into local part and domain
    try:
        account, domain = handle.split("@", 1)
    except ValueError:
        return None

    # Construct the WebFinger URL
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{account}@{domain}"

    # Perform the request and return the document text if successful
    try:
        response = requests.get(url, timeout=5)
    except Exception:
        return None

    if response.status_code != 200:
        return None

    return response.text<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        if '@' not in handle:
            return None
        acct = 'acct:' + handle
        import urllib.parse, urllib.request
        domain = handle.split('@', 1)[1]
        url = f'https://{domain}/.well-known/webfinger?' + urllib.parse.urlencode({'resource': acct})
        with urllib.request.urlopen(url, timeout=5) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
