def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    import urllib.parse

    # Ensure the handle is in the form acct:username@host
    if not handle.startswith("acct:"):
        if "@" not in handle:
            raise ValueError("handle must contain an '@' separator (e.g., 'user@example.com') or start with 'acct:'")
        user, host = handle.split("@", 1)
        resource = f"acct:{user}@{host}"
    else:
        resource = handle

    # Extract host part for the request URL
    try:
        _, host = resource.split("@", 1)
    except ValueError:
        raise ValueError(f"Invalid handle format: {handle}")

    # Build the WebFinger request URL
    webfinger_url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource)}"

    try:
        response = requests.get(webfinger_url, timeout=10)
    except requests.RequestException as exc:
        raise ValueError(f"Error fetching WebFinger document: {exc}") from exc

    if response.status_code != 200:
        raise ValueError(f"WebFinger request failed with status {response.status_code}")

    try:
        return response.json()
    except Exception as exc:
        raise ValueError(f"Invalid JSON in WebFinger response: {exc}") from exc<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        req_method = getattr(requests, method.lower())
    except AttributeError:
        return (None, ValueError(f"Unsupported request method: {method}"))
    try:
        response = req_method(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    file_names = []
    for dir_path in settings_dirs:
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    # If spec_option is None, accept all files.
                    # If spec_option is a string, include files that contain that substring.
                    # If spec_option is a tuple of extensions, accept matching extensions.
                    if spec_option is None:
                        file_names.append(full_path)
                    elif isinstance(spec_option, str):
                        if spec_option in entry:
                            file_names.append(full_path)
                    elif isinstance(spec_option, (list, tuple, set)):
                        if any(entry.endswith(ext) for ext in spec_option):
                            file_names.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return file_names<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    file_list = []

    for d in settings_dirs:
        if not os.path.isdir(d):
            continue
        for root, dirs, files in os.walk(d):
            for fname in files:
                if spec_option:
                    # treat spec_option as a glob pattern, e.g. '*.ini'
                    if not fnmatch.fnmatch(fname, spec_option):
                        continue
                file_list.append(os.path.join(root, fname))

    return sorted(file_list)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    from pathlib import Path

    file_names = []

    for dir_path in settings_dirs:
        path = Path(dir_path)
        if not path.is_dir():
            continue
        # Use glob pattern specified by spec_option
        for p in path.glob(spec_option):
            if p.is_file():
                file_names.append(str(p))
    return file_names<|return|>

