    if isinstance(include, str):
        includes = [include]
    elif isinstance(include, (list, tuple)):
        includes = list(include)
    else:
        raise ValueError(f"'include' directive must be a string or list of strings, got {type(include).__name__}")
    for name in includes:
        if not isinstance(name, str):
            raise ValueError(f"Included group name must be a string, got {type(name).__name__}")
        if not hasattr(self, 'group_defs'):
            raise AttributeError("The object does not have a 'group_defs' attribute to resolve includes")
        group = self.group_defs.get(name)
        if group is None:
            raise KeyError(f"Included group '{name}' not found in group definitions")
