def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their replacements (if any)
    deprecated_mapping = getattr(self, "_deprecated_args", {})

    # Helper to process a single dict of args
    def _process(args, source_name):
        for key in list(args):
            if key in deprecated_mapping:
                replacement = deprecated_mapping[key]
                if replacement:
                    # Prefer the new argument over the deprecated one
                    if replacement not in args:
                        args[replacement] = args.pop(key)
                        print(
                            f"[WARN] Argument '{key}' is deprecated (used via {source_name}). "
                            f"Please use '{replacement}' instead."
