def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            req_when = opt.get('required_when')
            if not req_when:
                continue

            # If the condition is a callable, invoke it with the command name and args.
            if callable(req_when):
                try:
                    if req_when(command_name, args):
                        required.append(opt.get('name'))
                except Exception:
                    # If the callable raises an exception, skip this option.
                    continue
            else:
                # Assume the condition is a string expression that can be evaluated.
                # The evaluation context has access to command_name and args.
                try:
                    if eval(req_when, {}, {'command_name': command_name, 'args': args}):
                        required.append(opt.get('name'))
                except Exception:
                    continue
        return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = []
        for opt in options_spec:
            # Support both dict-like and object-like specs
            opt_name = opt.get("name") if isinstance(opt, dict) else getattr(opt, "name", None)
            if not opt_name:
                continue

            # Get the condition that may enforce requirement
            cond = opt.get("required_when") if isinstance(opt, dict) else getattr(opt, "required_when", None)

            if cond is None:
                continue

            # If it's a callable, invoke it with args.  If it returns truthy,
            # the option becomes required in this context.
            try:
                if callable(cond):
                    if cond(args, command_name):
                        required.append(opt_name)
                else:
                    # Assume non-callable conditions are interpreted as truthy if
                    # they are simple boolean-like values.
                    if cond:
                        required.append(opt_name)
            except Exception:
                # On failure to evaluate, skip it and continue
                continue

        return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        cond = opt.get('required_when')
        if not cond:
            continue
        # Try to evaluate the condition – it can be a callable,
        # a string expression, or a simple boolean.
        matches = False
        if callable(cond):
            try:
                matches = bool(cond(args))
            except Exception:
                matches = False
        elif isinstance(cond, str):
            try:
                # use args dict as local namespace
                matches = bool(eval(cond, {}, args))
            except Exception:
                matches = False
        elif isinstance(cond, bool):
            matches = cond
        if matches:
            name = opt.get('name')
            if name:
                required.append(name)
    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_names = []

    for opt in options_spec:
        # Extract the option name. The spec might use different keys.
        name = opt.get('name') or opt.get('option') or opt.get('arg')
        if not name:
            continue

        required_when = opt.get('required_when')
        if not required_when:
            continue

        should_include = False
        try:
            if callable(required_when):
                should_include = bool(required_when(args))
            else:
                # Support string expressions; evaluate in a safe namespace
                safe_locals = {'command_name': command_name, 'args': args}
                should_include = bool(eval(required_when, {}, safe_locals))
        except Exception:
            # If evaluation fails, ignore this option
            continue

        if should_include:
            required_names.append(name)

    return required_names<|return|>

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditional_required = []

        for opt in options_spec:
            # Skip if no required_when clause
            required_when = opt.get('required_when')
            if required_when is None:
                continue

            # Evaluate the condition
            matched = False
            try:
                if callable(required_when):
                    # Callable receives command_name and args
                    matched = required_when(command_name, args)
                elif isinstance(required_when, str):
                    # Evaluate string as expression with command_name and args in context
                    # Example: "command_name == 'run'"
                    matched = bool(eval(required_when, {}, {
                        'command_name': command_name,
                        'args': args,
                    }))
                else:
                    # For other types, attempt direct truthiness
                    matched = bool(required_when)
            except Exception:
                # If evaluation fails, treat as not matched
                matched = False

            if matched:
                # Assume option name stored under 'name'
                name = opt.get('name')
                if name:
                    conditional_required.append(name)

        return conditional_required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Iterate over the supplied arguments
    for name, val in args.items():
        # Determine the maximum allowed length for this argument.
        max_len = None

        # Use explicit per-argument limits defined on the instance.
        if hasattr(self, 'allowed_lengths') and isinstance(self.allowed_lengths, dict):
            max_len = self.allowed_lengths.get(name)

        # Fallback to a common maximum length if no per-argument limit was set.
        if max_len is None and hasattr(self, 'max_length'):
            max_len = self.max_length

        # If no limit is specified, skip validation for this argument.
        if max_len is None:
            continue

        # Obtain the length of the value, converting to string if necessary.
        try:
            length = len(val)
        except TypeError:
            length = len(str(val))

        # Raise an error if the value exceeds the allowed length.
        if length > max_len:
            raise ValueError(f"Argument '{name}' is too long: {length} > {max_len}")<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

