def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Expect that `self` has an attribute `choices` mapping argument names to
    # iterables of allowed values. If no such attribute exists, nothing to validate.
    if not hasattr(self, "choices"):
        return

    # Normalise the incoming `args` to an iterable of (name, value) pairs.
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = args
    else:
        raise TypeError("args must be a dict or a list/tuple of (name, value) pairs")

    for name, value in items:
        if value is None:
            continue
        if name in self.choices:
            allowed = self.choices[name]
            if isinstance(value, (list, tuple)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{name}': {v!r}. "
                            f"Allowed choices are {allowed!r}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value!r}. "
                        f"Allowed choices are {allowed!r}"
                    )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # The mapping of argument names to allowed choices is expected to be
    # stored in the instance under the attribute `_choices` or `choices`.
    # If no such mapping exists, no validation is performed.
    choices_map = getattr(self, "_choices", None) or getattr(self, "choices", {})
    for arg, value in args.items():
        if arg not in choices_map:
            # No explicit choices defined for this argument – skip validation.
            continue

        allowed = choices_map[arg]

        # Normalise the allowed set into a sequence for membership checks.
        if isinstance(allowed, (list, tuple, set)):
            # If the value itself is a sequence (e.g., a multi‑choice field),
            # validate each element against the allowed set.
            iterable = value if isinstance(value, (list, tuple)) else (value,)
            for v in iterable:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value {v!r} for argument '{arg}'. "
                        f"Allowed values are: {sorted(allowed)}"
                    )
        else:
            # If the allowed specification is not a container, assume it
            # behaves like a predicate (callable that returns True/False
            # for a valid value).
            try:
                is_valid = bool(allowed(value))
                if not is_valid:
                    raise ValueError(
                        f"Invalid value {value!r} for argument '{arg}'. "
                        f"Allowed values specified by {allowed}."
                    )
            except Exception:
                raise ValueError(
                    f"Invalid value {value!r} for argument '{arg}'. "
                    f"Unable to validate against the provided allowed specification."
                )<|return|>

