def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # determine minimum and maximum limits defined on the object
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    if min_val is None or max_val is None:
        raise AttributeError("Both 'min' and 'max' attributes must be set for validation.")

    def _check_value(val):
        if val < min_val or val > max_val:
            raise ValueError(
                f"Argument value {val} is outside of allowed range "
                f"[{min_val}, {max_val}]."
            )

    # Support a single value or an iterable of values (except strings/bytes)
    if isinstance(args, (list, tuple, set)):
        for val in args:
            _check_value(val)
    else:
        _check_value(args)<|return|>

def validate_min_max_args(self, args):
