    if args is None:
        count = 0
    else:
        count = len(args)

    min_val = getattr(self, 'min_args', None)
    max_val = getattr(self, 'max_args', None)

    if min_val is not None and count < min_val:
        raise ValueError(f"{self.__class__.__name__} expects at least {min_val} arguments, got {count}.")

    if max_val is not None and count > max_val:
