def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Define a custom type function that validates and parses the argument
    def _complex_type(arg):
        # Enforce allowed choices if provided
        choices = spec_option.get("choices")
        if choices is not None and isinstance(arg, (str, int, float)):
            if arg not in choices:
                raise ValueError(
                    f"Argument '{option_name}' for subcommand '{subcommand}' "
                    f"must be one of {choices}, got {arg!r}"
                )
        # If argument should be parsed into a list (e.g., comma separated)
        if spec_option.get("list", False):
            if not isinstance(arg, str):
                raise TypeError(
                    f"Argument '{option_name}' for subcommand '{subcommand}' "
                    f"must be a string to split into a list."
                )
            return [item.strip() for item in arg.split(",") if item.strip()]
        # Default behaviour: return the argument as is
        return arg

    # Attach the custom type to the subcommand for later use (if needed)
    if not hasattr(subcommand, "__dict__"):
        # If subcommand is a plain string or other non-object, create a simple namespace
        subcommand = type("SubcommandNamespace", (), {})()
    if not hasattr(subcommand, "types"):
        subcommand.types = {}
    subcommand.types[type_name] = _complex_type

    return _complex_type<|return|>

