        if not isinstance(option_name, str):
            raise TypeError(f"option_name must be a string, got {type(option_name)!r}")

        # Normalise spec_option to a dictionary if it is None
        if spec_option is None:
            spec_option = {}

        # Construct a simple immutable representation of the complex type
        complex_type = {
            'subcommand': subcommand,
            'type_name': type_name,
            'option_name': option_name,
            'spec_option': spec_option
        }

        # Store the type in an internal registry for later lookup
        if not hasattr(self, '_complex_argument_types'):
            self._complex_argument_types = {}
