        return complex_type<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare dictionaries to collect control and nested arguments
    control_args = {}
    nested_args = {}

    # Handle if args is a dict or a list/tuple of (key, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        # Assume iterable of (key, value) pairs
        try:
            items = iter(args)
        except TypeError:
            raise TypeError("args must be a dict or iterable of (key, value) pairs")

    for key, value in items:
        # Convert key to string for direct comparison
        key_str = str(key)

        # Consider keys that start with '_' or with a 'ctrl_' prefix as control arguments
        if key_str.startswith('_') or key_str.lower().startswith('ctrl_'):
            control_args[key_str] = value
        else:
            # All other keys are treated as nested arguments (including custom ones)
            nested_args[key_str] = value

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # If args is a mapping
    if isinstance(args, dict):
        iterable = args.items()
    else:
        # Assume iterable of (key, value) pairs
        iterable = args

