def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import json, subprocess

    # Build the basic command
    cmd = ['ansible-playbook', playbook_path]

    # Add verbosity flags (e.g., -v, -vv)
    if verbose:
        try:
            level = int(verbose)
            if level > 0:
                cmd.append('-' + 'v' * level)
        except Exception:
            # If verbose is not an int, ignore
            pass

    # Add extra-vars if provided
    if extra_vars is not None:
        try:
            json_str = json.dumps(extra_vars)
            cmd.extend(['--extra-vars', json_str])
        except Exception as exc:
            raise ValueError("Failed to serialize extra_vars to JSON: %s" % exc)

    # Add extra ansible arguments if provided
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            if isinstance(val, bool):
                if val:
                    cmd.append(f'--{key}')
                # if False, skip this flag
                continue
            cmd.extend([f'--{key}', str(val)])

    # Execute the command
    try:
        result = subprocess.run(cmd, cwd=ir_workspace.path if hasattr(ir_workspace, 'path') else None,
                                capture_output=True, text=True, check=True)
    except subprocess.CalledProcessError as exc:
        # Log or re-raise as needed
        raise RuntimeError(f"Ansible playbook failed ({exc.returncode}): {exc.stderr}") from exc

    return result<|return|>

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """

    # Build the base command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity flag
    if verbose:
        try:
            level = int(verbose)
        except Exception:
            level = 0
        if level > 0:
            cmd.append("-" + "v" * level)

    # Add custom ansible playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if value is None or value is False:
                continue
            full_key = f"--{key}"
            if value is True:
                # Flag-only argument
                cmd.append(full_key)
            else:
                # Argument with value(s)
                if isinstance(value, (list, tuple)):
                    for v in value:
                        cmd.append(f"{full_key}={v}")
                else:
                    cmd.append(f"{full_key}={value}")

    # Add extra variables as json string
    if extra_vars:
        if isinstance(extra_vars, dict):
            try:
                import json
                ev_json = json.dumps(extra_vars)
            except Exception:
                ev_json = str(extra_vars)
        else:
            ev_json = str(extra_vars)
        cmd.extend(["--extra-vars", ev_json])

    # Logging the command
    try:
        ir_workspace.log(f"Running command: {' '.join(cmd)}")
    except Exception:
        try:
            ir_plugin.format(f"Running command: {' '.join(cmd)}")
        except Exception:
            # fallback to stdout
            print(f"Running command: {' '.join(cmd)}")

    # Execute the command
    import subprocess

    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        check=False,
    )

    # Handle errors
    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook exited with status {result.returncode}\n"
            f"Stdout:\n{result.stdout}\n"
            f"Stderr:\n{result.stderr}"
        )
        try:
            ir_workspace.error(error_msg)
        except Exception:
            try:
                ir_plugin.format(error_msg)
            except Exception:
                print(error_msg)

    return result<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Grab the expected types for each argument for this parser,
    # if such a mapping exists on the instance.
    specs = getattr(self, 'parser_specs', {}).get(parser_name, {})
    if not specs:
        # No type information available – nothing to convert.
        return

    # Iterate over the current keys; we copy the list to avoid
    # modifying the dict while iterating.
    for key in list(values_dict.keys()):
        val = values_dict[key]
        if val is None:
            continue

        target = specs.get(key)
        if target is None:
            # No type specified for this argument, skip conversion.
            continue

        try:
            if target is bool:
                if isinstance(val, str):
                    low = val.lower()
                    if low in ('true', '1', 'yes', 'y', 'on'):
                        casted = True
                    elif low in ('false', '0', 'no', 'n', 'off'):
                        casted = False
                    else:
                        casted = val
                else:
                    casted = bool(val)
            elif target is int:
                casted = int(val)
            elif target is float:
                casted = float(val)
            elif target is list:
                if isinstance(val, str):
                    casted = [x.strip() for x in val.split(',')]
                else:
                    casted = list(val)
            else:
                # Assume `target` is a callable conversion function.
                casted = target(val)
        except Exception:
            # If conversion fails, keep the original value.
            casted = val

        values_dict[key] = casted<|return|>

