def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")

    # Normalize the root by stripping trailing slashes or backslashes
    root = root.rstrip('/\\')

    # Check if the path starts with the root
    if path.startswith(root):
        remainder = path[len(root):]
    else:
        # Try matching with a following slash/backslash
        if path.startswith(root + '/'):
            remainder = path[len(root) + 1:]
        elif path.startswith(root + '\\'):
            remainder = path[len(root) + 1:]
        else:
            raise ValueError(f"Path '{path}' does not start with root '{root}'")

    # Remove a leading slash or backslash from the remainder, if present
    if remainder.startswith('/') or remainder.startswith('\\'):
        remainder = remainder[1:]

    return remainder<|return|>
